The following statements hold: 
\begin{enumerate}
    \item[a)]
    Let $s \in \mathbb{N}$, and $\mathcal{F}$ be a finite family of infinite  regular languages over an  alphabet of size $a\ge 2$ such that each $L \in \mathcal{F}$ is accepted by an NFA with at most $s$ states. Then $\mathcal{F}$ is $a^{s^{|\mathcal{F}|}}$-generatable. Moreover, the same result holds if each language in $\mathcal{F}$ is defined by a regular expression of length at most $s-1$.

  \item[b)] There exists $k \in \mathbb{N}$ such that, for every $\ell, n \in\mathbb{N}$ with $\ell \geq 1$ and $n \geq 1$, there exists a family $\mathcal{F}$ of infinite binary regular languages such that $|\mathcal{F}| = 2^\ell$, each $L \in\mathcal{F}$ is accepted by a DFA with at most $k \cdot \ell \cdot n$ states, and $\mathcal{F}$ is not $2^{n^{|\mathcal{F}|}}$-generatable. Moreover, the same result holds if each language in $\mathcal{F}$ is defined by a regular expression of length at most  $k \cdot \ell^2 \cdot n^2$.
\end{enumerate}

The following statements hold: 
	\begin{enumerate}
		\item[a)]
		Let $s \in \mathbb{N}$, and $\mathcal{F}$ be a finite family of infinite languages over an  alphabet of size $a\ge 2$ such that each $L \in \mathcal{F}$ is defined by an LTT of size at most $s$. Then $\mathcal{F}$ is $a^{3s|\mathcal{F}|((s|\mathcal{F}|)^2+1)^2}
		$-generatable. 

		\item[b)] For every $n \in\mathbb{N}$ with $n \geq 4$, there exists a family $\mathcal{F}$ of two infinite languages over an  alphabet of size $n$ such that  each $L \in\mathcal{F}$ is defined by a profile of length at most $7(n+1)$, and $\mathcal{F}$ is not $2^{n}$-generatable. 
	\end{enumerate}
